<?php
namespace App\Http\Controllers;

use App\Models\{Order,OrderItem,Product,SupportMessage,User};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;

class PortalController extends Controller
{
 public function dashboard(Request $r){$u=$r->user();if($u->isStaff()){$query=Order::with('customer','items');if($u->role==='rider')$query->where('status','out_for_delivery');$orders=$query->latest()->limit(20)->get();$stats=['orders'=>Order::whereNotIn('status',['delivered','cancelled'])->count(),'products'=>Product::where('is_active',true)->count(),'customers'=>User::where('role','customer')->count(),'low'=>Product::where('stock','<=',5)->count()];return view('portal.staff',compact('orders','stats'));}$orders=$u->orders()->with('items')->latest()->limit(6)->get();$products=Product::where('is_active',true)->orderBy('name')->limit(4)->get();return view('portal.customer',compact('orders','products'));}
 public function shop(Request $r){$q=Product::where('is_active',true);if($s=trim((string)$r->query('q')))$q->where(fn($x)=>$x->where('name','like',"%$s%")->orWhere('description','like',"%$s%"));$products=$q->orderBy('name')->paginate(12)->withQueryString();return view('portal.shop',compact('products'));}
 public function cart(){ $cart=session('cart',[]);$ids=array_keys($cart);$products=Product::whereIn('id',$ids)->get()->keyBy('id');$lines=[];$total=0;foreach($cart as $id=>$qty){if(!$p=$products->get($id))continue;$sub=$p->price*$qty;$total+=$sub;$lines[]=['product'=>$p,'quantity'=>$qty,'subtotal'=>$sub];}return view('portal.cart',compact('lines','total'));}
 public function addCart(Request $r,Product $product){$d=$r->validate(['quantity'=>'required|integer|min:1|max:99']);abort_unless($product->is_active,404);$cart=session('cart',[]);$qty=($cart[$product->id]??0)+$d['quantity'];if($qty>$product->stock)return back()->withErrors(['cart'=>'Not enough stock is available.']);$cart[$product->id]=$qty;session(['cart'=>$cart]);return back()->with('success','Added to cart.');}
 public function removeCart(Product $product){$cart=session('cart',[]);unset($cart[$product->id]);session(['cart'=>$cart]);return back()->with('success','Item removed.');}
 public function checkout(Request $r){$d=$r->validate(['customer_name'=>'required|string|max:120','phone'=>'required|string|max:30','delivery_address'=>'required|string|max:1000','note'=>'nullable|string|max:1000']);$cart=session('cart',[]);if(!$cart)return back()->withErrors(['cart'=>'Your cart is empty.']);$order=DB::transaction(function()use($cart,$d,$r){$products=Product::whereIn('id',array_keys($cart))->lockForUpdate()->get()->keyBy('id');$total=0;foreach($cart as $id=>$qty){$p=$products->get($id);if(!$p||!$p->is_active||$qty>$p->stock)throw \Illuminate\Validation\ValidationException::withMessages(['cart'=>'A product changed or no longer has enough stock. Please review your cart.']);$total+=$p->price*$qty;}$order=Order::create(['user_id'=>$r->user()->id,'order_number'=>'AT-'.now()->format('ymd').'-'.Str::upper(Str::random(5)),'delivery_token'=>Str::random(48),'status'=>'pending','total'=>$total]+$d);foreach($cart as $id=>$qty){$p=$products[$id];$p->decrement('stock',$qty);$order->items()->create(['product_id'=>$p->id,'product_name'=>$p->name,'quantity'=>$qty,'unit_price'=>$p->price,'subtotal'=>$p->price*$qty]);}return $order;});session()->forget('cart');return redirect()->route('orders.show',$order)->with('success','Order placed. We will update its status here.');}
 public function orders(Request $r){$u=$r->user();if($u->role==='rider')$query=Order::where('status','out_for_delivery');elseif($u->isStaff())$query=Order::query();else $query=$u->orders();$orders=$query->with('customer')->latest()->paginate($u->isStaff()?20:12);return view('portal.orders',compact('orders'));}
 public function showOrder(Request $r,Order $order){$u=$r->user();abort_unless(($u->isStaff()&&($u->role!=='rider'||$order->status==='out_for_delivery'||$order->delivered_by===$u->id))||$order->user_id===$u->id,403);$order->load('items','customer','rider');$feedback=DB::table('feedback')->where('order_id',$order->id)->where('user_id',$u->id)->exists();return view('portal.order',compact('order','feedback'));}
 public function status(Request $r,Order $order){$d=$r->validate(['status'=>'required|in:confirmed,preparing,out_for_delivery,cancelled']);if(!in_array($r->user()->role,['admin','staff'],true))abort(403);if(in_array($order->status,['delivered','cancelled']))abort(422,'This order is already closed.');DB::transaction(function()use($order,$d){if($d['status']==='cancelled'){foreach($order->items as $i)if($i->product_id)Product::whereKey($i->product_id)->increment('stock',$i->quantity);}$order->update(['status'=>$d['status']]);});return back()->with('success','Order status updated.');}
 public function delivery(Request $r,string $token){$order=Order::where('delivery_token',$token)->with('items','customer')->firstOrFail();abort_unless(in_array($r->user()->role,['admin','staff','rider'],true),403);return view('portal.delivery',compact('order'));}
 public function scanner(){return view('portal.scanner');}
 public function deliver(Request $r,string $token){$order=Order::where('delivery_token',$token)->firstOrFail();abort_unless(in_array($r->user()->role,['admin','staff','rider'],true),403);if($order->status!=='out_for_delivery')return back()->withErrors(['scan'=>'Order must be marked out for delivery first.']);$order->update(['status'=>'delivered','delivered_at'=>now(),'delivered_by'=>$r->user()->id]);return redirect()->route('orders.show',$order)->with('success','Delivery confirmed.');}
 public function feedback(Request $r,Order $order){abort_unless($order->user_id===$r->user()->id&&$order->status==='delivered',403);$d=$r->validate(['rating'=>'required|integer|between:1,5','comment'=>'nullable|string|max:2000']);DB::table('feedback')->updateOrInsert(['user_id'=>$r->user()->id,'order_id'=>$order->id],$d+['created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Thanks for your feedback!');}
 public function messages(Request $r){$u=$r->user();$customerId=$u->isStaff()?(int)$r->query('customer',$u->role==='customer'?$u->id:0):$u->id;if(!$customerId&&$u->isStaff()){$customerId=(int)(User::where('role','customer')->whereHas('orders')->orderBy('name')->value('id')??0);}abort_if(!$customerId,404);abort_unless($u->isStaff()||$customerId===$u->id,403);$customer=User::findOrFail($customerId);$messages=SupportMessage::with('sender')->where('user_id',$customerId)->oldest()->get();$customers=User::where('role','customer')->whereHas('supportMessages')->orderBy('name')->get();return view('portal.messages',compact('messages','customer','customers'));}
 public function sendMessage(Request $r){$d=$r->validate(['body'=>'required|string|max:2000','customer_id'=>'nullable|exists:users,id']);$u=$r->user();$cid=$u->isStaff()?(int)($d['customer_id']??0):$u->id;abort_unless($cid&&($u->isStaff()||$cid===$u->id),403);if($u->isStaff())abort_unless(User::whereKey($cid)->where('role','customer')->exists(),404);SupportMessage::create(['user_id'=>$cid,'sender_id'=>$u->id,'body'=>trim($d['body']),'is_staff_reply'=>$u->isStaff()]);return redirect()->route('messages',['customer'=>$cid])->with('success','Message sent.');}
 public function productsAdmin(){ $products=Product::orderByDesc('created_at')->paginate(15);return view('portal.products-admin',compact('products'));}
 public function saveProduct(Request $r,?Product $product=null){$d=$r->validate(['name'=>'required|string|max:140','description'=>'nullable|string|max:2000','price'=>'required|numeric|min:0|max:999999','stock'=>'required|integer|min:0|max:1000000','unit'=>'required|string|max:30','is_active'=>'nullable|boolean']);$d['is_active']=$r->boolean('is_active');if($r->hasFile('image')){$r->validate(['image'=>'image|mimes:jpg,jpeg,png,webp|max:3072']);$dir=public_path('product-images');if(!is_dir($dir))mkdir($dir,0755,true);$f=Str::uuid().'.'.$r->file('image')->extension();$r->file('image')->move($dir,$f);$d['image_path']='product-images/'.$f;}if($product)$product->update($d);else Product::create($d);return back()->with('success','Product saved.');}
 public function deleteProduct(Product $product){$product->update(['is_active'=>false]);return back()->with('success','Product removed from the shop.');}
 public function team(){abort_unless(auth()->user()->isAdmin(),403);$users=User::orderBy('role')->orderBy('name')->paginate(20);return view('portal.team',compact('users'));}
 public function setRole(Request $r,User $user){abort_unless(auth()->user()->isAdmin(),403);if($user->id===$r->user()->id)abort(422,'You cannot change your own role.');$d=$r->validate(['role'=>'required|in:customer,staff,rider,admin']);$user->update($d);return back()->with('success','User role updated.');}
}
